/**
 * `pnpm db:generate [--name <label>]`: diffs `src/server/db/global.schema.ts` against the last published
 * viborm estate state (`migrations/d1-estate/`) and writes the forward SQL as the next numbered file in
 * `migrations/d1/` (`NNNN_<label>.sql`), which `wrangler d1 migrations apply` runs. viborm's D1 driver
 * refuses live migrations, so this only ever runs offline.
 *
 * Review the generated file before committing it: it is the SQL production executes.
 */
import { mkdirSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createClient } from 'viborm/d1';
import { createMigrationClient } from 'viborm/migrations';
import { createFsStorageWriter } from 'viborm/migrations/storage/fs';
import { GLOBAL_TABLES, globalSchema } from '../src/server/db/global.schema.ts';

const SQL_DIR = 'migrations/d1';
const ESTATE_DIR = 'migrations/d1-estate';

const nameFlag = process.argv.indexOf('--name');
const label = (nameFlag === -1 ? process.argv[2] : process.argv[nameFlag + 1]) ?? 'global';
const slug = label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'global';

// Offline generation never touches the binding.
const client = createClient({ database: {} as D1Database, schema: globalSchema });
mkdirSync(ESTATE_DIR, { recursive: true });
const migrations = createMigrationClient(client, {
	storage: createFsStorageWriter(ESTATE_DIR),
	tables: GLOBAL_TABLES
} as Parameters<typeof createMigrationClient>[1]);

const result = (await migrations.generate({ name: slug })) as {
	outcome: string;
	reviewSql?: string;
	stateId?: string;
	warnings?: unknown[];
};
if (result.outcome === 'noop') {
	console.log('Schema already matches the last state: nothing to generate.');
	process.exit(0);
}
if (result.outcome !== 'published' || !result.reviewSql) {
	console.error('Unexpected generate result:', result.outcome);
	process.exit(1);
}

/** The forward statements of every parent transition: the sections labelled `FORWARD execute`. */
function forwardSql(review: string): string {
	const statements: string[] = [];
	const lines = review.split('\n');
	let collecting = false;
	let current: string[] = [];
	const flush = () => {
		const text = current.join('\n').trim();
		if (text) statements.push(text.endsWith(';') ? text : `${text};`);
		current = [];
	};
	for (const line of lines) {
		if (line.startsWith('-- ')) {
			if (collecting) flush();
			collecting = line.startsWith('-- FORWARD execute');
			continue;
		}
		if (collecting) current.push(line);
	}
	if (collecting) flush();
	return statements.join('\n\n');
}

const sql = forwardSql(result.reviewSql);
if (!sql) {
	console.error('No forward SQL found in the review output.');
	process.exit(1);
}
const next =
	readdirSync(SQL_DIR)
		.map((file) => /^(\d{4})_/.exec(file)?.[1])
		.filter((n): n is string => n !== undefined)
		.reduce((max, n) => Math.max(max, Number(n)), -1) + 1;
const file = join(SQL_DIR, `${String(next).padStart(4, '0')}_${slug}.sql`);
writeFileSync(file, `-- Generated by viborm (pnpm db:generate), state ${result.stateId}.\n\n${sql}\n`);
console.log(`Wrote ${file}`);
for (const warning of result.warnings ?? []) console.warn('warning:', warning);
